package com.example.com.englishai.backend.infrastructure.security; import com.example.com.englishai.backend.application.ports.PasswordResetCodeHasher; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.util.Base64;
public class HmacPasswordResetCodeHasher implements PasswordResetCodeHasher { private final byte[] secret; public HmacPasswordResetCodeHasher(String s){if(s==null||s.isBlank())throw new IllegalArgumentException("Password reset code hash secret is required");try{secret=Base64.getDecoder().decode(s);}catch(IllegalArgumentException e){throw new IllegalArgumentException("Password reset code hash secret must be valid Base64");}if(secret.length<32)throw new IllegalArgumentException("Password reset code hash secret must contain at least 32 bytes");} public String hash(String c){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret,"HmacSHA256"));StringBuilder b=new StringBuilder(64);for(byte v:m.doFinal(c.getBytes(java.nio.charset.StandardCharsets.UTF_8)))b.append("%02x".formatted(v&255));return b.toString();}catch(Exception e){throw new IllegalStateException("Unable to hash password reset code");}} }
